package com.vandorlabs.neoforge.copifier;
import com.vandorlabs.neoforge.light.*;
import com.vandorlabs.neoforge.redstone.*;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Installed canonical Light leaf commits, output publication and whole-process restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierLightWorldChecks {
 private static final BlockPos BASE=new BlockPos(18100,82,18100);private static int checks;
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Copied Light: "+text);}
 private static NativeLightEntity at(ServerLevel world,BlockPos pos){return (NativeLightEntity)world.getBlockEntity(pos);}
 private static NativeLightEntity put(ServerLevel world,BlockPos pos,Block block,boolean join){world.getChunkAt(pos);world.setBlock(pos,block.defaultBlockState().setValue(NativeLightBlock.FACING,Direction.NORTH),18);var owner=at(world,pos);var tag=owner.saveWithoutMetadata(world.registryAccess());tag.putBoolean("LightJoin",join);tag.putBoolean("LightOn",true);tag.putString("CopiedLightFuture","opaque:retained");var caps=new CompoundTag();caps.putString("Owner","opaque:cap");tag.put("ForgeCaps",caps);owner.loadWithComponents(tag,world.registryAccess());owner.onLoad();NativeLightService.refresh(owner);return owner;}
 private static void write(ServerLevel world){var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new java.util.UUID(0,1880),"CopiedLights"));actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var blocks=new Block[]{NativeLightRegistrations.BLOCK.get(),NativeLightRegistrations.FRAME.get(),NativeLightRegistrations.SLAB.get()};for(int family=0;family<3;family++){var pos=BASE.south(family*5);var owner=put(world,pos,blocks[family],true);var peer=put(world,pos.east(),blocks[family],true);NativeLightService.refresh(owner);var values=new CompoundTag();values.putBoolean("active",false);values.putInt("light_level",7);var original=values.copy();var state=owner.getBlockState();actor.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()-2);need(NativeCopifierHousingWorld.capture(world,pos,actor,Direction.NORTH)!=null,"common Light capture");NativeCopifierUndo.begin(actor,world);try{need(NativeCopifierHousingWorld.applySingle(world,pos,actor,Direction.NORTH,values),"selected leaf accepts copied ACTIVE family="+family);}finally{NativeCopifierUndo.finish(actor);}need(!owner.settings().light().manualOn&&peer.settings().light().manualOn,"copied ACTIVE leaves joined sibling unchanged");need(owner.getBlockState()==state&&values.equals(original),"clipboard and pose immutable");var saved=owner.saveWithoutMetadata(world.registryAccess());need(saved.getString("CopiedLightFuture").equals("opaque:retained")&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:cap"),"opaque host data preserved");var bad=new CompoundTag();bad.putInt("texture_layout",99);bad.putBoolean("active",true);var before=owner.saveWithoutMetadata(world.registryAccess());need(!owner.configureCopied(bad)&&owner.saveWithoutMetadata(world.registryAccess()).equals(before),"invalid all-field preflight leaves owner exact");need(NativeCopifierUndo.undo(actor)&&owner.settings().light().manualOn&&peer.settings().light().manualOn,"common selected Light undo");need(NativeCopifierHousingWorld.applySingle(world,pos,actor,Direction.NORTH,values),"common reapply for restart");world.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);}
 var pos=BASE.west(5);var source=put(world,pos,blocks[0],false);var receiver=put(world,pos.north(3),blocks[0],false);var receive=new CompoundTag();receive.putInt("redstone_channel",923);receive.putInt("redstone_trigger",1);receive.putBoolean("signal_settings",false);need(receiver.configureCopied(receive),"receiver copied channel");var values=new CompoundTag();var tx=new CompoundTag();tx.putIntArray("Channels",new int[]{923});tx.putInt("Range",16);tx.putBoolean("Local",false);values.put("Transmission",tx);world.setBlock(pos.south(),Blocks.REDSTONE_BLOCK.defaultBlockState(),18);need(source.configureCopied(values),"copied transmission installed");need(source.transmission().channels().equals(ChannelList.of(923))&&source.transmittedChannels().isEmpty(),"Source configured transmission is metadata only for Light");NativeRedstoneChannels.outputChanged(source);NativeLightService.refresh(receiver);need(receiver.inheritedSettings().channelLevel()==0,"physical input is never repeated by Light");world.setBlock(pos.south(),Blocks.AIR.defaultBlockState(),18);NativeLightService.refresh(source);NativeLightService.refresh(receiver);need(receiver.inheritedSettings().channelLevel()==0,"physical withdrawal clears configured output");var retired=source;world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(!retired.configureCopied(values),"stale identity cannot mutate replacement");
 var failedPos=BASE.east(6);var failed=put(world,failedPos,blocks[0],false);var future=failed.saveWithoutMetadata(world.registryAccess());future.putInt("NativeLightSchema",99);failed.loadWithComponents(future,world.registryAccess());var edit=new CompoundTag();edit.putBoolean("active",false);need(!failed.configureCopied(edit)&&failed.saveWithoutMetadata(world.registryAccess()).equals(future),"inert original refuses copied edits exactly");var installed=at(world,BASE);var installedBefore=installed.saveWithoutMetadata(world.registryAccess());need(!java.util.concurrent.CompletableFuture.supplyAsync(()->installed.configureCopied(edit)).join()&&installed.saveWithoutMetadata(world.registryAccess()).equals(installedBefore),"worker refused before ownership/world queries");
 var cold=BASE.offset(1024,0,1024);while((cold.getX()&15)!=0)cold=cold.east();while((cold.getZ()&15)!=0)cold=cold.south();var owner=put(world,cold,blocks[0],true);need(world.getChunkSource().getChunkNow((cold.getX()-1)>>4,cold.getZ()>>4)==null,"cold boundary starts absent");var coldValues=new CompoundTag();coldValues.putBoolean("active",false);need(owner.configureCopied(coldValues),"cold leaf copy accepts");need(world.getChunkSource().getChunkNow((cold.getX()-1)>>4,cold.getZ()>>4)==null,"copy grouping does not load cold neighbor");
 }
 private static void read(ServerLevel world){world.getChunkAt(BASE);var failed=at(world,BASE.east(6));need(failed.inert()&&failed.saveWithoutMetadata(world.registryAccess()).getInt("NativeLightSchema")==99,"inert original restart unchanged");for(int family=0;family<3;family++){var pos=BASE.south(family*5);world.getChunkAt(pos);var owner=at(world,pos);var peer=at(world,pos.east());NativeLightService.refresh(owner);need(owner!=null&&!owner.settings().light().manualOn&&owner.settings().light().configuredLevel==7&&peer.settings().light().manualOn,"copied leaf and sibling retained after restart family="+family);need(owner.saveWithoutMetadata(world.registryAccess()).getString("CopiedLightFuture").equals("opaque:retained"),"opaque retention restart");}}
 @SubscribeEvent public static void started(ServerStartedEvent event){var phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.equals("copifier-light-write")&&!phase.equals("copifier-light-read"))return;var world=event.getServer().overworld();if(phase.endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][copifier-light] "+(phase.endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
